<script setup lang="ts">
import {ref} from 'vue';import {useRouter,useRoute} from 'vue-router';import {auth,signIn,signUp} from '@/stores/auth';
const props=defineProps<{mode:'login'|'register'}>();const router=useRouter(),route=useRoute();const name=ref(''),phone=ref(''),email=ref(''),password=ref(''),error=ref(''),loading=ref(false);
async function submit(){error.value='';loading.value=true;try{if(props.mode==='login')await signIn(email.value,password.value);else await signUp(name.value,phone.value,email.value,password.value);const next=typeof route.query.next==='string'?route.query.next:auth.user?.role==='admin'?'/admin':auth.user?.role==='instructor'?'/instructor':'/account';await router.push(next)}catch(e){error.value='Не удалось загрузить'}finally{loading.value=false}}
</script><template><div class="container section"><div class="card panel form-card"><h1 class="h2">{{mode==='login'?'Вход в аккаунт':'Регистрация'}}</h1><form class="form-stack" @submit.prevent="submit"><label v-if="mode==='register'">Имя<input v-model.trim="name" required minlength="2" class="field"/></label><label v-if="mode==='register'">Телефон<input v-model.trim="phone" required class="field" type="tel"/></label><label>Email<input v-model.trim="email" required class="field" type="email"/></label><label>Пароль<input v-model="password" required minlength="6" class="field" type="password"/></label><p v-if="error" class="state-error">{{error}}</p><button class="btn btn--primary" :disabled="loading">{{loading?'Подождите...':mode==='login'?'Войти':'Зарегистрироваться'}}</button></form><RouterLink class="link" :to="mode==='login'?'/register':'/login'">{{mode==='login'?'Создать аккаунт':'Уже есть аккаунт? Войти'}}</RouterLink></div></div></template>
